<?php
require 'config.php'; wajib_admin();
$pesan='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $id=(int)($_POST['id']??0); $status=$_POST['status']??'terkirim'; $nilai=trim($_POST['nilai']??''); $feedback=trim($_POST['feedback']??'');
  if(in_array($status,['terkirim','dinilai','revisi'],true) && ($nilai==='' || (is_numeric($nilai)&&$nilai>=0&&$nilai<=100))){
    $st=$pdo->prepare('UPDATE pengumpulan SET status=?,nilai=?,feedback=? WHERE id=?');
    $st->execute([$status,$nilai===''?null:$nilai,$feedback,$id]); $pesan='Status pengumpulan berhasil diperbarui.';
  } else $pesan='Nilai harus berada di antara 0 sampai 100.';
}
$sql="SELECT p.*, t.judul, t.mata_kuliah, u.nama, u.nim FROM pengumpulan p JOIN tugas t ON t.id=p.tugas_id JOIN users u ON u.id=p.mahasiswa_id ORDER BY p.dikumpulkan_at DESC";
$rows=$pdo->query($sql)->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pengumpulan — Aroby Assignment</title><link rel="stylesheet" href="style.css"></head><body><aside class="sidebar"><a class="brand" href="dashboard.php">Aroby <span>Assignment</span></a><div class="side-label">MENU UTAMA</div><a class="nav" href="dashboard.php">▦ &nbsp; Dashboard</a><a class="nav" href="tambah_tugas.php">＋ &nbsp; Tambah Tugas</a><a class="nav active" href="pengumpulan_admin.php">▤ &nbsp; Pengumpulan</a><div class="side-bottom"><div class="avatar">A</div><div class="user-mini"><b><?=e($_SESSION['user']['nama'])?></b><small>Admin</small></div><a class="logout" href="logout.php">↪</a></div></aside><main class="main"><header class="topbar"><div><span class="eyebrow">MONITORING</span><h1>Pengumpulan Mahasiswa</h1></div></header><?php if($pesan): ?><div class="success"><?=e($pesan)?></div><?php endif; ?><section class="panel"><div class="panel-head"><div><h3>Semua berkas masuk</h3><p>Unduh berkas dan perbarui status atau nilai.</p></div><span class="pill"><?=count($rows)?> pengumpulan</span></div><div class="table-wrap"><table><thead><tr><th>MAHASISWA</th><th>TUGAS</th><th>BERKAS</th><th>STATUS / NILAI</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?=e($r['nama'])?></b><small class="subline"><?=e($r['nim'])?></small></td><td><?=e($r['judul'])?><small class="subline"><?=e($r['mata_kuliah'])?></small></td><td><a class="text-link" href="download.php?id=<?=$r['id']?>"><?=e($r['file_asli'])?> ↓</a><small class="subline"><?=e(date('d/m/Y H:i',strtotime($r['dikumpulkan_at'])))?></small></td><td><form method="post" class="inline-form"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="terkirim" <?=$r['status']==='terkirim'?'selected':''?>>Terkirim</option><option value="dinilai" <?=$r['status']==='dinilai'?'selected':''?>>Dinilai</option><option value="revisi" <?=$r['status']==='revisi'?'selected':''?>>Revisi</option></select><input class="grade" type="number" name="nilai" min="0" max="100" step="0.01" placeholder="Nilai" value="<?=e($r['nilai']??'')?>"><input name="feedback" placeholder="Feedback" value="<?=e($r['feedback']??'')?>"><button class="small-btn">Simpan</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4" class="empty">Belum ada mahasiswa yang mengumpulkan tugas.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
